from html import escape
from urllib.parse import urlencode
from .content import projects, services, sectors, extra, quality

nav={'projects':('Projects','المشروعات'),'services':('Services','الخدمات'),'about':('About','عن الشركة'),'gallery':('Gallery','من مواقعنا'),'quality':('Quality','الجودة'),'contact':('Contact us','تواصل معنا')}
parties={'role':('Our role','دور الشركة'),'owner':('Owner','المالك'),'client':('Client','العميل'),'consultant':('Consultant','الاستشاري'),'contractor':('Main contractor','المقاول الرئيسي')}
def photo(id): return f'/assets/photos/Im{id}.webp'
def image(id,label='',lazy=True): return f'<img src="{photo(id)}" alt="{escape(label,quote=True)}" {"loading=lazy" if lazy else ""} decoding="async">'
def render(lang,path,query):
    ar=lang=='ar'
    def t(en,arabic):return arabic if ar else en
    def link(route):return '/'+lang+'/'+route
    def cta(route,title,style='btn'):return f'<a class="{style}" href="{link(route)}">{title}<span class="arrow" aria-hidden="true">↗</span></a>'
    def tag(s):return f'<div class="tag">{s}</div>'
    def heading(s,desc=''):return f'<div class="heading"><h1>{s}</h1><p>{desc}</p></div>'
    def card(key):
        p=projects[key]
        return f'<a class="card" data-sector="{p["sector"]}" data-services="{" ".join(p["services"])}" href="{link("projects/"+key)}">{image(p["photos"][0])}<div class="meta">{t(*sectors[p["sector"]])} · {t(*p["place"])}</div><h3>{t(*p["name"])} <span class="arrow">↗</span></h3></a>'
    def service_rows():
        return ''.join(f'<a class="service-row" href="{link("services/"+k)}"><h3>{t(*s[0])}</h3><span class="arrow">↗</span></a>' for k,s in services.items())
    def stats():
        return '<div class="stats">'+''.join(f'<div><strong dir="ltr">{n}</strong><span>{s}</span></div>' for n,s in [('2020',t('Year founded','سنة التأسيس')),('20+',t('Projects','مشروعًا')),('20',t('Engineers & technicians','مهندسًا وفنيًا')),('02',t('Countries of operation','مصر والسعودية'))])+'</div>'
    def media(k,i):
        p=projects[k];name=t(*p['name']); label=f'{name} · {p["photos"].index(i)+1}'
        return f'<button class="media" data-project="{k}" data-photo="{photo(i)}" data-title="{label}" data-link="{link("projects/"+k)}" aria-label="{label}">{image(i,label)}<span>{name} <b>⤢</b></span></button>'
    def opts(items,first):return '<option value="">'+first+'</option>'+''.join(f'<option value="{k}">{v}</option>' for k,v in items)
    def profile():return f'<a class="outline" download href="/assets/company-profile.pdf">{t("Download company profile","تحميل ملف الشركة")} ↓</a>'
    key,_,slug=path.partition('/')
    title=t(*nav.get(key,('MEP contracting','مقاولات كهروميكانيكية')))
    if not key:
        slides=[(799,'middor',t('Fire pump room','غرفة مضخات الحريق')),(898,'ain-shams',t('Cable routing','مسارات الكابلات')),(1333,'neom',t('Fire pump system','منظومة ضخ الحريق'))]
        frames=''.join(f'<figure class="frame" {"" if n==0 else "hidden"}>{image(i,t(*projects[k]["name"]),False)}<figcaption><small>{s}</small><a href="{link("projects/"+k)}">{t(*projects[k]["name"])} ↗</a></figcaption></figure>' for n,(i,k,s) in enumerate(slides))
        buttons=''.join(f'<button data-slide="{i}" aria-label="{t(*projects[k]["name"])}" aria-pressed="{str(i==0).lower()}"></button>' for i,(_,k,_) in enumerate(slides))
        body=f'''<section class="hero"><div class="hero-copy">{tag(t('MEP CONTRACTING  /  EST. 2020','مقاولات كهروميكانيكية  /  منذ ٢٠٢٠'))}<h1>{t('Engineering <br>behind every <br><em>system.</em>','هندسة وراء <br><em>كل نظام.</em>')}</h1><p>{t('Mechanical, electrical and plumbing works for residential, commercial and industrial projects in Egypt and Saudi Arabia.','ننفّذ الأعمال الميكانيكية والكهربائية والصحية للمشروعات السكنية والتجارية والصناعية في مصر والسعودية.')}</p><div class="actions">{cta('projects',t('Explore projects','استكشف مشروعاتنا'))}{cta('services',t('Our services','خدماتنا'),'plain')}</div></div><div class="hero-media">{frames}<div class="controls"><div class="dots">{buttons}</div><button id="pause" aria-label="{t('Pause or play slideshow','إيقاف أو تشغيل عرض الصور')}">Ⅱ</button></div></div></section>{stats()}'''
        body+=f'<section><div class="sectiontop"><h2>{t("Selected projects","مشروعات مختارة")}</h2>{cta("projects",t("All projects","كل المشروعات"),"plain")}</div><div class="rail">' + ''.join(card(k) for k in ['neom','ain-shams','mercury','royal-walk','middor'])+f'</div><div class="rail-buttons"><button data-scroll="-1" aria-label="{t("Previous","السابق")}">‹</button><button data-scroll="1" aria-label="{t("Next","التالي")}">›</button></div></section>'
        body+=f'<section class="split">{image(281)}<div>{tag(t("CAPABILITIES","تخصصاتنا"))}<h2>{t("Our services","خدماتنا")}</h2>{service_rows()}</div></section>'
    elif key=='projects' and not slug:
        body=heading(title,t('Explore our scope of work across Egypt and Saudi Arabia.','اكتشف نطاق أعمالنا في مصر والسعودية.'))
        body+=f'<div class="filters"><select id="sector" aria-label="{t("Sector","القطاع")}">{opts(((k,t(*v)) for k,v in sectors.items()),t("All sectors","كل القطاعات"))}</select><select id="service" aria-label="{t("Service","الخدمة")}">{opts(((k,t(*v[0])) for k,v in services.items()),t("All services","كل الخدمات"))}</select></div><div class="grid">'+''.join(card(k) for k in projects)+f'</div><p hidden id="empty">{t("No projects match these filters.","لا توجد مشروعات بهذه الاختيارات.")}</p><section><h2>{t("Other project references","أعمال أخرى من سجل الشركة")}</h2><ul class="list">'+''.join(f'<li>{t(*v)}</li>' for v in extra)+'</ul></section>'
    elif key=='projects' and slug in projects:
        p=projects[slug];title=t(*p['name'])
        body=cta('projects',t('All projects','كل المشروعات'),'plain')+heading(title,t(*p['place']))+f'<div class="detailhero">{image(p["photos"][0],title,False)}</div><section class="columns"><div><h2>{t("Scope of work","نطاق الأعمال")}</h2><ul>'+''.join(f'<li>{t(*v)}</li>' for v in p['scope'])+'</ul></div><dl>'+''.join(f'<dt>{t(*parties[k])}</dt><dd>{t(*v)}</dd>' for k,v in p['parties'].items())+'</dl></section><div class="grid">'+''.join(media(slug,i) for i in p['photos'][1:])+'</div>'+cta('contact?project='+slug,t('Discuss a similar project','ناقش مشروعًا مشابهًا'))
    elif key=='services' and not slug:
        body=heading(title,t('From design coordination to installation and handover.','من تنسيق التصميمات إلى التركيب والتسليم.'))+'<div class="grid two">'+''.join(f'<a class="card" href="{link("services/"+k)}">{image(s[1])}<h3>{t(*s[0])} ↗</h3><p>{t(*s[2][0])}</p></a>' for k,s in services.items())+'</div>'
    elif key=='services' and slug in services:
        s=services[slug];title=t(*s[0]);body=heading(title)+f'<div class="split">{image(s[1])}<ul>'+''.join(f'<li>{t(*v)}</li>' for v in s[2])+f'</ul></div><section><h2>{t("Related projects","مشروعات مرتبطة")}</h2><div class="grid">'+''.join(card(k) for k,p in projects.items() if slug in p['services'])+'</div></section>'
    elif key=='gallery':
        body=heading(title,t('Installations, equipment and site work from our project archive.','صور التركيبات والمعدات ومراحل العمل من أرشيف مشروعاتنا.'))
        body+=f'<div class="filters"><select id="gallery-project" aria-label="{t("Project","المشروع")}">{opts(((k,t(*p["name"])) for k,p in projects.items()),t("All projects","كل المشروعات"))}</select><select id="kind" aria-label="{t("Media type","نوع الوسائط")}">{opts([("photo",t("Photos","صور")),("video",t("Video","فيديو"))],t("All media","كل الوسائط"))}</select></div><div class="grid"><figure class="movie" data-project="middor"><video controls playsinline preload="none" poster="{photo(799)}" src="/assets/middor.webm"></video><figcaption>{t("Middor Mall · Photo film · 12 sec","ميدور مول · عرض مصوّر · ١٢ ثانية")}</figcaption></figure>'+''.join(media(k,i) for k,p in projects.items() for i in p['photos'])+f'</div><p hidden id="empty">{t("No media matches these filters.","لا توجد وسائط بهذه الاختيارات.")}</p>'
    elif key=='about':
        body=heading(t('About Red Owl','عن ريد أول'),t('MEP contractors in Egypt and Saudi Arabia since 2020.','مقاولات كهروميكانيكية في مصر والسعودية منذ ٢٠٢٠.'))+stats()+f'<section class="split">{image(121,t("Youssef Gouda","يوسف جودة"))}<div>{tag(t("FROM THE CHAIRMAN","كلمة رئيس مجلس الإدارة"))}<blockquote>{t("“We pay close attention to detail, respect every schedule and treat each project as a long-term partnership.”","«نولي التفاصيل عناية كبيرة، ونحترم الجداول الزمنية، ونتعامل مع كل مشروع كشراكة طويلة الأمد.»")}</blockquote><p>{t("Youssef Gouda · Chairman","يوسف جودة · رئيس مجلس الإدارة")}</p>{profile()}</div></section><section><h2>{t("Vision and mission","الرؤية والرسالة")}</h2><p>{t("We aim to be a trusted engineering partner, delivering integrated systems safely, on time and within budget. Our values are quality, commitment, safety, innovation and integrity.","نسعى لنكون شريكًا هندسيًا موثوقًا ينفّذ الأنظمة المتكاملة بأمان، في الموعد وضمن الميزانية. قيمنا هي الجودة والالتزام والسلامة والابتكار والنزاهة.")}</p></section>'
    elif key=='quality':
        body=heading(t('Quality & certifications','الجودة والشهادات'),t('Quality checks from material approval to final handover.','مراجعات الجودة من اعتماد المواد وحتى التسليم النهائي.'))+'<div class="quality">'+''.join(f'<article><h3>{t(*a)}</h3><p>{t(*b)}</p></article>' for a,b in quality)+'</div>'+f'<section class="split">{image(324)}<div><h2>{t("ISO documentation","وثائق الأيزو")}</h2><p>{t("For qualification and tender documentation, contact the Red Owl team.","لطلب مستندات التأهيل والجودة الخاصة بالمناقصات، تواصل مع فريق ريد أول.")}</p>{cta("contact?type=quality",t("Request documentation","طلب مستندات الجودة"))}</div></section>'
    elif key=='contact':
        title=t('Discuss your project','ناقش مشروعك معنا')
        fields=[('name',t('Name','الاسم'),'text'),('company',t('Company','الشركة'),'text'),('email',t('Email','البريد الإلكتروني'),'email')]
        k=query.get('project',[''])[0];pref=t(*projects[k]['name']) if k in projects else ''
        choices={'project':t('Project inquiry','استفسار عن مشروع'),'tender':t('Tender invitation','دعوة لمناقصة'),'quality':t('Qualification documents','مستندات التأهيل')}
        body=heading(title)+f'<div class="columns contact"><div><h3>{t("Cairo office","مكتب القاهرة")}</h3><p>{t("Villa 328, 90th Street, South Academy C, Fifth Settlement","فيلا ٣٢٨، شارع التسعين، جنوب الأكاديمية ج، التجمع الخامس")}</p><a dir="ltr" href="tel:+201000695256">+20 100 069 5256</a><br><a href="mailto:info@redowlco.com">info@redowlco.com</a></div><form action="/api/inquiry" method="post" enctype="multipart/form-data"><input type="hidden" name="lang" value="{lang}"><label>{t("Inquiry type","نوع الطلب")}<select name="type">'+''.join(f'<option value="{i}" {"selected" if i==query.get("type",[""])[0] else ""}>{v}</option>' for i,v in choices.items())+'</select></label>'+''.join(f'<label>{label}<input name="{n}" type="{typ}" required maxlength="200"></label>' for n,label,typ in fields)+f'<label>{t("Project brief","تفاصيل الطلب")}<textarea name="message" required maxlength="5000">{pref}</textarea></label><label>{t("Tender document (optional PDF, up to 5 MB)","مستند المناقصة (PDF اختياري حتى ٥ ميجابايت)")}<input type="file" name="attachment" accept="application/pdf"></label><small>{t("Local preview · submissions are saved on this device.","نسخة محلية · يُحفظ الطلب على هذا الجهاز.")}</small><button class="btn">{t("Save inquiry","حفظ الطلب")}</button></form></div>'
    elif key=='received':
        body=heading(t('Inquiry saved','تم حفظ طلبك'),t('Your inquiry has been recorded on this device.','تم تسجيل تفاصيل الطلب على هذا الجهاز.'))+cta('projects',t('Explore projects','استكشف المشروعات'))
    else:raise KeyError(path)
    menu=''.join(f'<a href="{link(k)}" {"aria-current=page" if k==key else ""}>{t(*v)}</a>' for k,v in nav.items() if k!='contact')
    logo=f'<a class="logo" href="{link("")}">{image(7,"Red Owl Construction",False)}</a>'; other='/'+t('ar','en')+'/'+path+('?' + escape(urlencode(query,doseq=True)) if query else '')
    return f'''<!doctype html><html lang="{lang}" dir="{t("ltr","rtl")}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#d7141e"><title>{title} | Red Owl Construction</title><link rel="icon" href="{photo(7)}"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script></head><body><a class="skip" href="#main">{t("Skip to content","تخطّ إلى المحتوى")}</a><header>{logo}<nav id="nav">{menu}</nav><div class="headtools"><a href="{other}" lang="{t("ar","en")}">{t("العربية","English")}</a>{cta("contact",t("Contact us","تواصل معنا"))}<button id="menu" aria-controls="nav" aria-expanded="false" aria-label="{t("Menu","القائمة")}">☰</button></div></header><main id="main">{body}</main><footer><div>{logo}<p>{t("Mechanical, electrical & plumbing contractors","مقاولات الأعمال الميكانيكية والكهربائية والصحية")}</p></div><div>{profile()}<p><a href="mailto:info@redowlco.com">info@redowlco.com</a></p></div></footer><dialog aria-label="{t("Photo viewer","عارض الصور")}"><button class="close" aria-label="{t("Close","إغلاق")}">×</button><img id="large" alt=""><div class="viewer"><button data-step="-1" aria-label="{t("Previous","السابق")}">‹</button><a id="caption"></a><button data-step="1" aria-label="{t("Next","التالي")}">›</button></div></dialog></body></html>'''
